function isValidDistribution(ps) {
  let total = 0;
  for (const p of ps) total += p;
  return Math.abs(total - 1) < 1e-9;
}

function bestLabel(options) {
  let best = options[0];
  for (const o of options) if (o.ev > best.ev) best = o;
  return best.label;
}

