function padlockSaving(lockCost, pBefore, pAfter, loss) {
  const saved = (pBefore - pAfter) * loss;
  return Math.round((saved - lockCost) * 100) / 100;
}

function evOfBet(p, win, lose) {
  const ev = p * win - (1 - p) * lose;
  return Math.round(ev * 100) / 100;
}

function sumProbabilities(ps) {
  let total = 0;
  for (const p of ps) total += p;
  return Math.round(total * 10000) / 10000;
}

function expectedValue(outcomes) {
  let total = 0;
  let ev = 0;
  for (const o of outcomes) {
    total += o.p;
    ev += o.p * o.v;
  }
  if (Math.abs(total - 1) > 1e-9) throw new Error("probabilities must sum to 1");
  return Math.round(ev * 100) / 100;
}

function breakEvenProbability(okValue, lossValue, rivalEv) {
  const p = (okValue - rivalEv) / (okValue - lossValue);
  return Math.round(p * 10000) / 10000;
}

function foldTree(node) {
  let result;
  if ("value" in node) {
    result = node.value;
  } else if (node.chance) {
    result = 0;
    for (const b of node.chance) result += b.p * foldTree(b.node);
  } else {
    result = -Infinity;
    for (const option of node.choose) result = Math.max(result, foldTree(option));
  }
  return Math.round(result * 100) / 100;
}
